package com.loopers.application.event
import com.loopers.domain.event.*;import com.loopers.infrastructure.event.OutboxJpaRepository;import com.loopers.infrastructure.order.OrderJpaRepository;import com.loopers.utils.DatabaseCleanUp;import org.assertj.core.api.Assertions.assertThat;import org.junit.jupiter.api.*;import org.junit.jupiter.api.assertThrows;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.*;import org.springframework.context.annotation.*
@SpringBootTest @Import(OutboxCrashWindowTest.Config::class) class OutboxCrashWindowTest @Autowired constructor(private val service:OrderOutboxService,private val relay:OutboxRelay,private val outbox:OutboxJpaRepository,private val orders:OrderJpaRepository,private val publisher:ControlledPublisher,private val cleanup:DatabaseCleanUp){@AfterEach fun clean(){cleanup.truncateAllTables();publisher.reset()};@Test fun orderAndOutboxCommitOrRollbackTogether(){service.create("event-ok",135135,1000,false);assertThat(orders.count()).isEqualTo(1);assertThat(outbox.count()).isEqualTo(1);assertThrows<RuntimeException>{service.create("event-rollback",135135,1000,true)};assertThat(orders.count()).isEqualTo(1);assertThat(outbox.count()).isEqualTo(1)};@Test fun crashAfterAckPublishesTwiceButEffectIsOnce(){val e=service.create("event-1",135135,1000,false);assertThrows<OutboxRelay.CrashAfterPublish>{relay.relay(e.id,true)};relay.relay(e.id,false);assertThat(publisher.deliveries).isEqualTo(2);assertThat(publisher.effects).containsExactly("event-1");assertThat(outbox.findById(e.id).orElseThrow().status).isEqualTo(OutboxEvent.Status.PUBLISHED)};@TestConfiguration class Config{@Bean @Primary fun publisher()=ControlledPublisher()}};class ControlledPublisher:OutboxPublisher{var deliveries=0;val effects=mutableSetOf<String>();override fun publish(eventId:String,payload:String){deliveries++;effects+=eventId};fun reset(){deliveries=0;effects.clear()}}
